import { TripNotes } from './TripNotes'

export function Itinerary() {
  return (
    <main>
      <h1>Itinerary</h1>
      <TripNotes />
    </main>
  )
}

import { useState } from 'react'

/** Free-form notes for a trip, saved in the browser. */
export function TripNotes({ tripId }: { tripId: string }) {
  const key = `notes:${tripId}`
  const [text, setText] = useState(() => localStorage.getItem(key) ?? '')
  return <textarea value={text} onChange={(e) => (setText(e.target.value), localStorage.setItem(key, e.target.value))} />
}
